async function main() {
  let successCount = 0;
  let failedCount = 0;

  const category = await prisma.category.upsert({
    where: { slug: categorySlug },
    update: { name: categoryName, group: "Technology" },
    create: { name: categoryName, slug: categorySlug, group: "Technology" },
  });

  const subcategories = new Map<string, string>();
  for (const item of questions) {
    if (!subcategories.has(item.subcategorySlug)) {
      const sub = await prisma.subcategory.upsert({
        where: { categoryId_slug: { categoryId: category.id, slug: item.subcategorySlug } },
        update: { name: item.subcategoryName },
        create: { name: item.subcategoryName, slug: item.subcategorySlug, categoryId: category.id },
      });
      subcategories.set(item.subcategorySlug, sub.id);
    }
  }

  for (const item of questions) {
    try {
      const subcategoryId = subcategories.get(item.subcategorySlug);
      await prisma.interviewQuestion.upsert({
        where: { slug: item.slug },
        update: {
          question: item.question, categoryId: category.id, subcategoryId,
          experienceLevel: item.experienceLevel, difficulty: item.difficulty, interviewType: item.interviewType,
          shortDescription: item.shortDescription, explanation: item.explanation, sampleAnswer: item.sampleAnswer,
          detailedAnswer: item.detailedAnswer, keyPoints: item.keyPoints, commonMistakes: item.commonMistakes,
          followUpQuestions: item.followUpQuestions, tags: item.tags, seoTitle: item.seoTitle,
          seoDescription: item.seoDescription, isPublished: item.isPublished,
        },
        create: {
          question: item.question, slug: item.slug, categoryId: category.id, subcategoryId,
          experienceLevel: item.experienceLevel, difficulty: item.difficulty, interviewType: item.interviewType,
          shortDescription: item.shortDescription, explanation: item.explanation, sampleAnswer: item.sampleAnswer,
          detailedAnswer: item.detailedAnswer, keyPoints: item.keyPoints, commonMistakes: item.commonMistakes,
          followUpQuestions: item.followUpQuestions, tags: item.tags, seoTitle: item.seoTitle,
          seoDescription: item.seoDescription, isPublished: item.isPublished,
        },
      });
      successCount++;
    } catch (error) {
      console.error(`Failed question: ${item.question}`, error);
      failedCount++;
    }
  }

  console.log(`Digital Marketing interview seed completed. Success: ${successCount}, Failed: ${failedCount}`);
}

main()
  .catch((error) => {
    console.error("Seed failed:", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
